'use strict';
const jwt = require('jsonwebtoken');

// BR-01: every endpoint requires a valid bearer token. AS-04/BR-01 gap: no identity
// provider is named for issuing it, so this verifies with HS256 when JWT_SECRET is
// configured, and otherwise falls back to accepting any structurally valid, unexpired
// token carrying employee_id and role — the shape of the token, not its origin.
function auth(req, res, next) {
  const header = req.headers.authorization || '';
  const token = header.startsWith('Bearer ') ? header.slice(7) : null;
  if (!token) return res.status(401).json({ error: 'unauthorized', message: 'missing Authorization header' });

  try {
    const secret = process.env.JWT_SECRET;
    const payload = secret ? jwt.verify(token, secret) : jwt.decode(token);
    if (!payload || !payload.employee_id || !payload.role) {
      return res.status(401).json({ error: 'unauthorized', message: 'token missing employee_id/role' });
    }
    if (payload.exp && Date.now() >= payload.exp * 1000) {
      return res.status(401).json({ error: 'unauthorized', message: 'token expired' });
    }
    req.employeeId = payload.employee_id;
    req.role = payload.role;
    next();
  } catch {
    return res.status(401).json({ error: 'unauthorized', message: 'invalid token' });
  }
}

module.exports = auth;

'use strict';
const express = require('express');
const mongoose = require('mongoose');
const Employee = require('../models/Employee');
const LeaveRequest = require('../models/LeaveRequest');
const auth = require('../middleware/auth');

const router = express.Router();
const MS_PER_DAY = 24 * 60 * 60 * 1000;

// API-01 (BR-01, BR-03): submit a leave request.
router.post('/leave-requests', auth, async (req, res) => {
  const { start_date, end_date, reason } = req.body || {};
  const start = new Date(start_date);
  const end = new Date(end_date);
  if (!start_date || !end_date || Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || end < start) {
    return res.status(422).json({ error: 'invalid_request', message: 'end_date must be on or after start_date' });
  }
  if (!reason || typeof reason !== 'string' || reason.length > 500) {
    return res.status(422).json({ error: 'invalid_request', message: 'reason is required, max 500 chars' });
  }

  const employee = await Employee.findById(req.employeeId);
  if (!employee) return res.status(401).json({ error: 'unauthorized', message: 'employee not found' });

  const days = Math.round((end - start) / MS_PER_DAY) + 1;
  const doc = await LeaveRequest.create({
    employee_id: employee._id,
    manager_id: employee.manager_id,
    start_date: start,
    end_date: end,
    days,
    reason,
    status: 'pending',
  });
  res.status(201).json({ id: doc._id, status: doc.status, days: doc.days });
});

// API-02 (BR-01, BR-02): list requests scoped to the caller — an employee sees their
// own, a manager additionally sees requests routed to them.
router.get('/leave-requests', auth, async (req, res) => {
  const { status } = req.query;
  const filter = { $or: [{ employee_id: req.employeeId }] };
  if (req.role === 'manager') filter.$or.push({ manager_id: req.employeeId });
  if (status) filter.status = status;

  const items = await LeaveRequest.find(filter).sort({ created_at: -1 }).lean();
  res.json({ items });
});

async function decide(req, res, nextStatus) {
  const request = await LeaveRequest.findById(req.params.id);
  if (!request) return res.status(404).json({ error: 'not_found' });

  // BR-02/BR-06: only the named manager may decide, and never their own request.
  if (String(request.manager_id) !== String(req.employeeId) || String(request.employee_id) === String(req.employeeId)) {
    return res.status(401).json({ error: 'unauthorized', message: 'not this request\'s manager' });
  }
  // BR-04: only a pending request can be decided.
  if (request.status !== 'pending') {
    return res.status(409).json({ error: 'already_decided', message: `request is already ${request.status}` });
  }

  if (nextStatus === 'approved') {
    // BR-05: an approval that would overdraw the balance is refused, atomically —
    // the balance check and decrement happen in one conditional update so a race
    // between two approvals can't double-spend the same days.
    const employee = await Employee.findOneAndUpdate(
      { _id: request.employee_id, leave_balance_days: { $gte: request.days } },
      { $inc: { leave_balance_days: -request.days } },
      { new: true },
    );
    if (!employee) return res.status(409).json({ error: 'insufficient_balance' });
    request.status = 'approved';
    request.decided_at = new Date();
    await request.save();
    return res.json({ id: request._id, status: request.status, employee_balance_days: employee.leave_balance_days });
  }

  request.status = 'rejected';
  request.decided_at = new Date();
  await request.save();
  res.json({ id: request._id, status: request.status });
}

// API-03 (BR-04, BR-05, BR-06)
router.patch('/leave-requests/:id/approve', auth, (req, res) => decide(req, res, 'approved').catch((e) => res.status(400).json({ error: 'bad_request', message: e.message })));
// API-04 (BR-04, BR-06)
router.patch('/leave-requests/:id/reject', auth, (req, res) => decide(req, res, 'rejected').catch((e) => res.status(400).json({ error: 'bad_request', message: e.message })));

// API-05 (BR-02)
router.get('/leave-balance', auth, async (req, res) => {
  const employee = await Employee.findById(req.employeeId).lean();
  if (!employee) return res.status(401).json({ error: 'unauthorized' });
  res.json({ employee_id: employee._id, leave_balance_days: employee.leave_balance_days });
});

module.exports = router;

